"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[131],{2036(e){e.exports=JSON.parse('{"title":"2025\ub144, JavaScript","date":"2025-01-17","coverUrl":"/kudzu-based-bench/assets/notion/78e587d084b0f99e.png","html":"<h2 data-notion-block-id=\\"17ce548d-8a8e-80b8-9f76-c03a1a0338af\\" id=\\"17ce548d-8a8e-80b8-9f76-c03a1a0338af\\">2025\ub144, JavaScript</h2><a href=\\"https://dev.to/this-is-learning/javascript-frameworks-heading-into-2025-hkb\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://dev.to/this-is-learning/javascript-frameworks-heading-into-2025-hkb</a><p data-notion-block-id=\\"17ce548d-8a8e-80e4-8557-dbe097654464\\">SolidJS\uc758 \uc800\uc790\uac00 2024\ub144\uc5d0 JavaScript \uc0dd\ud0dc\uacc4\ub294 \uc5b4\ub290 \ubc29\uba74\uc5d0 \uc9d1\uc911\ud588\ub294\uc9c0, \uadf8\ub9ac\uace0 2025\ub144\uc740 \uc5b4\ub5bb\uac8c \ud758\ub7ec\uac08\uc9c0 \uc608\uc0c1\ud574\ubcf4\ub294 \uae00\uc785\ub2c8\ub2e4. \uc800\uc790\uc758 \ub9d0\ub300\ub85c, \uadf8\ub3d9\uc548 \ud504\ub860\ud2b8\uc5d4\ub4dc\uc758 \ubb38\uc81c\ub97c \ud574\uacb0\ud558\uae30 \uc704\ud574 \ud504\ub860\ud2b8\uc5d4\ub4dc\ub97c \uad6c\uc131\ud558\ub294 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\uc758 \ubcf5\uc7a1\uc131\uc774 \ub9e4\uc6b0 \uc99d\uac00\ud588\uc2b5\ub2c8\ub2e4. \uadf8\ub807\uae30\uc5d0 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc5b4\ub5bb\uac8c \ub300\ud558\ub294\uc9c0\uc5d0 \ub300\ud574 \ub354 \uc9d1\uc911\ud574\uc57c \ud569\ub2c8\ub2e4(\ucd94\ucc9c\ud558\ub294 \uae00 \ubb36\uc74c\uc73c\ub85c\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/15ee548d-8a8e-80b5-9d6e-cfa07648afc4#162e548d-8a8e-80c6-8224-f9618dd9926f\\">Next.js\uc5d0\uc11c Astro\ub85c \ubcc0\uacbd\ud558\uae30</a>, \uadf8 \uc911\uc5d0\uc11c <a href=\\"https://infrequently.org/2024/11/if-not-react-then-what/\\">React\ub97c \uc120\ud0dd\ud558\uc9c0 \uc54a\ub294\ub2e4\uba74</a>\uc744 \ucd94\ucc9c\ub4dc\ub9bd\ub2c8\ub2e4).</p><h2 data-notion-block-id=\\"17ce548d-8a8e-80a3-867c-da7b9c8c715a\\" id=\\"17ce548d-8a8e-80a3-867c-da7b9c8c715a\\">\uac15\uc81c reflow\ub85c height \uc560\ub2c8\uba54\uc774\uc158 \uad6c\ud604\ud558\uae30</h2><a href=\\"https://macarthur.me/posts/box/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://macarthur.me/posts/box/</a><p data-notion-block-id=\\"17ce548d-8a8e-80da-9799-c1ab8c44119d\\"><code>interpolate-size</code>\ub77c\ub294 \uc0c8\ub85c\uc6b4 CSS \ud0a4\uc6cc\ub4dc\ub97c \ud1b5\ud574\uc11c, \ud639\uc740 transform\uc744 \ud1b5\ud574\uc11c \uad6c\ud604\ud560 \uc218\ub3c4 \uc788\uc9c0\ub9cc(<a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8033-a90c-e3ad6ea49f73\\"><code>height: auto;</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/109e548d-8a8e-8006-bd2d-e5cd889b8dc5#109e548d-8a8e-8033-a90c-e3ad6ea49f73\\">\uac00 \uc560\ub2c8\uba54\uc774\uc158 \uc791\ub3d9\uc774 \uc548\ub418\uc694</a>\ub97c \ucc38\uace0\ud558\uc138\uc694), \uad6c\ud604 \uc2dc\uac04\uc774\ub098 \uc9c0\uc6d0 \ube0c\ub77c\uc6b0\uc800 \uc81c\ud55c\uc73c\ub85c \ubd88\uac00\ub2a5\ud560 \ub54c\ub3c4 \uc788\uc2b5\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \uac00\uc7a5 \uae30\ubcf8\uc801\uc73c\ub85c JS\uc640 \ube0c\ub77c\uc6b0\uc800 \ub80c\ub354\ub9c1 \ubc29\uc2dd\uc744 \ud65c\uc6a9\ud574\uc11c height \uc560\ub2c8\uba54\uc774\uc158 \uc791\ub3d9\uc744 \ubcf4\uc5ec\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"179e548d-8a8e-805d-bba4-da70fa8eebf6\\" id=\\"179e548d-8a8e-805d-bba4-da70fa8eebf6\\">GraphQL \uc0dd\ud0dc\uacc4, \uadf8\ub9ac\uace0 \ubca4\uce58\ub9c8\ud06c</h2><a href=\\"https://tomekdev.com/posts/benchmarking-graphql-solutions-in-the-js-ts-landscape\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://tomekdev.com/posts/benchmarking-graphql-solutions-in-the-js-ts-landscape</a><p data-notion-block-id=\\"17ce548d-8a8e-8024-827e-e33dc64622fe\\">GraphQL\uc744 \uc9c4\uc785\ud560 \ub54c \uac00\uc7a5 \ubb38\uc81c\uac00 \ub418\ub294 \uac83\uc774 \uc5b4\ub5a4 \ub77c\uc774\ube0c\ub7ec\ub9ac \uae30\ubc18\uc73c\ub85c \uc2dc\uc791\ud574\uc57c \ud558\ub294\uac00\uc5d0 \ub300\ud55c \uace0\ubbfc\uc785\ub2c8\ub2e4. \uc774\ub97c \ub300\ub7b5\uc801\uc73c\ub85c \uc54c\ub824\uc8fc\uae30 \uc704\ud574 GraphQL \uc0dd\ud0dc\uacc4\ub97c \uac04\ub2e8\ud558\uac8c \uc54c\uc544\ubcf4\uace0 \uadf8\uc5d0 \ub300\ud55c \ubca4\uce58\ub9c8\ud06c\ub97c \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ubaa8\ub4e0 \uc9c0\uc6d0 \uc0ac\ud56d(ex. federation, gateway)\uc774\ub098 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub97c \uc54c\ub824\uc8fc\ub294 \uac83\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc0dd\ud0dc\uacc4\ub97c \uc9c4\uc785\ud558\ub294\ub370\uc5d0 \ub300\ud55c \uc815\ubcf4\ub294 \uc798 \uc815\ub9ac\ub418\uc5b4\uc788\ub124\uc694.</p><h2 data-notion-block-id=\\"17ce548d-8a8e-8021-8cff-f4d2642ab823\\" id=\\"17ce548d-8a8e-8021-8cff-f4d2642ab823\\">RSC\uacfc Server action \uc2dc\ub3c4\ud558\uae30</h2><a href=\\"https://github.com/orgs/web-infra-dev/discussions/23\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/orgs/web-infra-dev/discussions/23</a><p data-notion-block-id=\\"17ce548d-8a8e-80b7-a38c-d214573ee92d\\">rspack\uc758 \uba54\uc778\ud14c\uc774\ub108\uac00 RSC\uc640 Server action\uc744 webpack, turbopack \uae30\ubc18\uc73c\ub85c \uad6c\uc131\ud574\ubcf4\uba70 RSC, SSR, Server Action\uc774 \uc5b4\ub5bb\uac8c \ud63c\ud569\ub418\ub294\uc9c0 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uae00\uc744 \uc77d\uc73c\ub824\uba74 webpack\uc758 optimizing\uc758 \uae30\ubcf8 \uac1c\ub150\uc740 \uc54c\uc544\uc57c\ud558\uae30\uc5d0, \uc880 \uc5b4\ub824\uc6b8 \uc218 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ce548d-8a8e-8067-bc2d-fc8a428764bf\\" id=\\"17ce548d-8a8e-8067-bc2d-fc8a428764bf\\">\uc811\uadfc\uc131\uc744 \ub300\ud558\ub294 \uc790\uc138</h2><a href=\\"https://github.com/Heydon/principles-of-web-accessibility\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://github.com/Heydon/principles-of-web-accessibility</a><p data-notion-block-id=\\"17ce548d-8a8e-80bc-9a4a-ca585a51fa41\\">\uc811\uadfc\uc131\uc774\ub77c\ub294 \ub2e8\uc5b4\uac00 \ubaa8\ud638\ud558\uae30\ub3c4\ud558\uace0, \ub9ce\uc740 \uc758\ubbf8\ub97c \ub0b4\ud3ec\ud558\uae30\ub3c4 \ud569\ub2c8\ub2e4. \uc774 \uae00\uc5d0\uc11c\ub294 \ubaa8\ud638\ud55c \uc811\uadfc\uc131 \uad6c\ud604\uc5d0 \ub300\ud55c \uc790\uc2e0\ub9cc\uc758 \uc6d0\uce59\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. \uad6c\ud604\ud558\ub294 \ubc29\ubc95\uc5d0 \ub300\ud574 \uc54c\ub824\uc8fc\uc9c4 \uc54a\uc9c0\ub9cc, \uc5b4\ub5bb\uac8c \ub300\ud574\uc57c \ud558\ub294\uc9c0, \uc5b4\ub5bb\uac8c \uc811\uadfc\ud574\uc57c \ud558\ub294\uc9c0\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ce548d-8a8e-80d9-8a2e-d6f536ea47c2\\" id=\\"17ce548d-8a8e-80d9-8a2e-d6f536ea47c2\\"><code>\\"use cache\\"</code>\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4</h2><a href=\\"https://nextjs.org/blog/composable-caching\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://nextjs.org/blog/composable-caching</a><p data-notion-block-id=\\"17ce548d-8a8e-806c-b8e3-d87c6b69affc\\">\uc774\uc804\uc5d0 <code>unstable_cache</code>\ub85c \uc81c\uacf5\ub418\ub294 Next.js\uc758 \uae30\ub2a5\uc774 <code>\\"use cache\\"</code>\ub514\ub809\ud2f0\ube0c\ub85c \uc81c\uacf5\ub429\ub2c8\ub2e4. React\uc758 <code>cache</code>\ud568\uc218\uc640 \ub2e4\ub978 \uc810\uacfc \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud558\ub294\uc9c0\ub97c \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ce548d-8a8e-80a9-9db5-eb784b07bad5\\" id=\\"17ce548d-8a8e-80a9-9db5-eb784b07bad5\\">\uc811\uadfc\uc131, \uadf8\ub9ac\uace0 \uc2a4\ud06c\ub9b0 \ub9ac\ub354</h2><a href=\\"https://www.epicweb.dev/testing-accessibility-with-screen-readers\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.epicweb.dev/testing-accessibility-with-screen-readers</a><p data-notion-block-id=\\"17ce548d-8a8e-8074-8fe8-e47cecf9455b\\">\uc2a4\ud06c\ub9b0 \ub9ac\ub354\uc5d0 \ub300\ud55c \uc0c1\uc138\ud55c \uc18c\uac1c\uc640 \uc8fc\ub85c \ud14c\uc2a4\ud2b8\ud574\uc57c \ud558\ub294 \ubd80\ubd84\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc2a4\ud06c\ub9b0 \ub9ac\ub354\ub97c \ud1b5\ud574 \uc218\ub3d9 \ud14c\uc2a4\ud2b8\ub97c \uc9c4\ud589\ud574\uc57c \ud560 \ub54c \ubcf4\uba74 \uc88b\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"17ce548d-8a8e-80e4-bfdf-dad7b49f7829\\" id=\\"17ce548d-8a8e-80e4-bfdf-dad7b49f7829\\"><code>text-wrap</code>\uc758 \uc0c8\ub85c\uc6b4 \uac12\ub4e4</h2><a href=\\"https://ishadeed.com/article/balancing-text-css/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/balancing-text-css/</a><p data-notion-block-id=\\"17ce548d-8a8e-80fa-a8d1-e9cfece2d0a4\\">\uc2dc\uac01\uc801\uc778 \uc815\ubcf4\uc640 \ud568\uaed8 <code>text-wrap</code>\uc758 \uc0c8\ub85c\uc6b4 \uac12\ub4e4\uc744 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \uc544\uc9c1 \uc8fc\uc694 \ube0c\ub77c\uc6b0\uc800\uc5d0\uc11c \ubaa8\ub450 \uc9c0\uc6d0\ud558\uc9c0\ub294 \uc54a\uc9c0\ub9cc, \uc2dc\uac01\uc801\uc778 \uc815\ubcf4\uc640 \ud568\uaed8 \uc5b4\ub514\uc11c \uc5b4\ub5bb\uac8c \uc0ac\uc6a9\ud574\uc57c\ud558\ub294\uc9c0 \uc774\ud574\ud558\uae30 \uc88b\uac8c \uc54c\ub824\uc90d\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"17ce548d-8a8e-80e6-ba57-c78c27d2fd8a\\" id=\\"17ce548d-8a8e-80e6-ba57-c78c27d2fd8a\\">Express.js\uacfc 2025\ub144</h2><a href=\\"https://expressjs.com/2025/01/09/rewind-2024-triumphs-and-2025-vision.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://expressjs.com/2025/01/09/rewind-2024-triumphs-and-2025-vision.html</a><p data-notion-block-id=\\"17ce548d-8a8e-80ea-b380-e8182ec5f6e1\\">Express.js 5.0\uc774 \ucd9c\uc2dc\ub418\uace0 \uadf8 \uc774\ud6c4\uc758 Express.js\ub294 \uc5b4\ub5bb\uac8c \ud758\ub7ec\uac08\uc9c0 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ub2e4\ub978 \uc11c\ubc84 \ub77c\uc774\ube0c\ub7ec\ub9ac\ub4e4\ub85c \ub300\uccb4\ub420\uc9c0, \uc544\ub2c8\uba74 Express.js\uac00 \ud601\uc2e0\uc744 \ud1b5\ud574 \uc9c4\ud654\ub420\uc9c0\ub294 \uc9c0\ucf1c\ubd10\uc57c\uaca0\ub124\uc694.</p>"}')}}]);